/** Business truth is structured evidence, never a sentence generated by Gus. */
import type { Receipt, SoundEntity } from './types';

export type Evidence<T> = {
  value: T;
  source: 'operator' | 'primary' | 'provider' | 'fixture';
  label: string;
  url?: string;
  observedAt: number;
  expiresAt: number;
};
export type Candidate = {
  id: string;
  name: string;
  mapping: { status: 'verified' | 'unresolved' | 'ambiguous'; entityId: string | null };
  locality: Evidence<string> | null;
  live: Evidence<boolean> | null;
  format: 'music' | 'comedy';
  capacity: Evidence<number> | null;
  fee: Evidence<number> | null;
  availability: Evidence<{ date: string; status: 'available' | 'unavailable' | 'unknown' }> | null;
  /** An intake route is not permission to send. Never sent to Qloo. */
  intake: Evidence<string> | null;
  genres: string[];
};
export type Opportunity = {
  id: string;
  artistId: string;
  mode: 'fixture' | 'operator';
  version: number;
  city: string;
  date: string;
  format: 'music' | 'comedy';
  roomCapacity: number;
  maxFee: number;
  status: 'planning' | 'canceled';
  roster: Candidate[];
  act: SoundEntity[];
  scene: SoundEntity[];
  sceneEvidence: Evidence<string>;
  updatedAt: number;
};
export type Qualification = { id: string; status: 'eligible' | 'blocked' | 'unverified'; reasons: string[]; warnings: string[] };
export type CulturalScore = { entityId: string; affinity: number; rank: number };
export type RankingView = { scores: CulturalScore[]; receipt: Receipt | null; error: string | null };
export type PressureRow = Qualification & { name: string; actRank: number | null; sceneRank: number | null; jointRank: number | null; worstRank: number | null };
export type PressureTest = {
  opportunityId: string;
  version: number;
  rows: PressureRow[];
  views: { act: RankingView; scene: RankingView; joint: RankingView };
  selectedId: string | null;
  baselineId: string | null;
  policyName: 'balanced' | 'strict';
  policy: string;
  explanation: string;
  observedAt: number;
};
export type ActionState = 'prepared' | 'approved' | 'executing' | 'provider_accepted' | 'acknowledged' | 'completed' | 'failed' | 'uncertain' | 'invalidated';
export type BookingAction = {
  id: string;
  artistId: string;
  opportunityId: string;
  version: number;
  candidateId: string;
  businessKey: string;
  mode: 'fixture' | 'operator';
  state: ActionState;
  payload: { date: string; payee: string; amount: number; currency: 'usd'; kind: 'support-request' };
  approval: { token: string; payloadHash: string; expiresAt: number; approvedAt: number } | null;
  receipt: { provider: 'fixture-inbox'; ref: string; acceptedAt: number; acknowledgment: string | null } | null;
  reason: string | null;
  createdAt: number;
  updatedAt: number;
};
export type ReplyInput = { sourceMessageId: string; contactId: string; expectedVersion: number; patch: { date?: string; maxFee?: number; canceled?: boolean } };
export type OperationEvent = { id: string; opportunityId: string; version: number; kind: string; detail: string; createdAt: number; change?: { before: Pick<Opportunity, 'date' | 'maxFee' | 'status'>; after: Pick<Opportunity, 'date' | 'maxFee' | 'status'> } };
export type Desk = { opportunity: Opportunity; pressure: PressureTest | null; actions: BookingAction[]; events: OperationEvent[]; metrics: { fixtureEffects: number; awaitingApproval: number; invalidatedActions: number } };
export type SensitivityReport = { version: number; baselineSelectedId: string | null; variants: { removedReference: string; selectedId: string | null; act: RankingView; error: string | null }[]; status: 'stable' | 'sensitive' | 'inconclusive'; detail: string; observedAt: number };

export function validDate(value: string): boolean {
  return /^\d{4}-\d{2}-\d{2}$/.test(value) && Number.isFinite(Date.parse(`${value}T12:00:00Z`)) && new Date(`${value}T12:00:00Z`).toISOString().slice(0, 10) === value;
}
export function currentEvidence<T>(e: Evidence<T> | null, now: number, mode: Opportunity['mode']): e is Evidence<T> {
  return !!e && Number.isFinite(e.observedAt) && Number.isFinite(e.expiresAt) && e.observedAt <= now && e.expiresAt > now && !!e.label.trim() && (mode === 'fixture' || e.source !== 'fixture');
}

/** Hard constraints come before taste. Unknown is not zero affinity or an invented fact. */
export function qualify(candidate: Candidate, show: Opportunity, now = Date.now()): Qualification {
  const reasons: string[] = [];
  const missing: string[] = [];
  if (show.status === 'canceled') reasons.push('Show canceled');
  if (candidate.format !== show.format) reasons.push('Wrong performance format');
  if (candidate.mapping.status !== 'verified' || !candidate.mapping.entityId) missing.push('Qloo mapping unresolved');
  if (!currentEvidence(candidate.locality, now, show.mode)) missing.push('Locality missing or stale');
  else if (candidate.locality.value !== show.city) reasons.push('Not in this circuit');
  if (!currentEvidence(candidate.live, now, show.mode)) missing.push('Live suitability not verified');
  else if (!candidate.live.value) reasons.push('Live suitability rejected');
  if (!currentEvidence(candidate.capacity, now, show.mode)) missing.push('Scale not verified');
  else if (!Number.isFinite(candidate.capacity.value) || candidate.capacity.value > show.roomCapacity || candidate.capacity.value <= 0) reasons.push('Wrong room scale');
  if (!currentEvidence(candidate.fee, now, show.mode)) missing.push('Fee missing or stale');
  else if (!Number.isFinite(candidate.fee.value) || candidate.fee.value > show.maxFee || candidate.fee.value < 0) reasons.push('Outside support budget');
  if (!currentEvidence(candidate.availability, now, show.mode) || candidate.availability.value.date !== show.date || candidate.availability.value.status === 'unknown') missing.push('Performance availability not confirmed for this date');
  else if (candidate.availability.value.status === 'unavailable') reasons.push('Unavailable on this date');
  if (!currentEvidence(candidate.intake, now, show.mode)) missing.push('Intake route missing or stale');
  return { id: candidate.id, status: reasons.length ? 'blocked' : missing.length ? 'unverified' : 'eligible', reasons: [...reasons, ...missing], warnings: show.mode === 'fixture' ? ['Fictional eligibility, not a verified local artist'] : [] };
}

/** A successful HTTP response without every required finite affinity fails the evidence gate. */
export function validateRanking(pool: string[], scores: { entityId: string; affinity: number | null }[]): CulturalScore[] {
  if (!pool.length || new Set(pool).size !== pool.length) throw new Error('Candidate pool must be nonempty and unique.');
  const seen = new Set<string>();
  for (const s of scores) {
    if (!pool.includes(s.entityId)) throw new Error('Qloo returned an outside candidate.');
    if (seen.has(s.entityId)) throw new Error('Qloo returned a duplicate candidate.');
    if (typeof s.affinity !== 'number' || !Number.isFinite(s.affinity)) throw new Error('Missing affinity: HTTP success is not cultural evidence.');
    seen.add(s.entityId);
  }
  if (seen.size !== pool.length) throw new Error('Qloo did not score the entire supplied roster.');
  // Preserve ties: entity-ID alphabetical order is not a cultural tie breaker.
  const sorted = [...scores].sort((a, b) => b.affinity! - a.affinity!);
  return sorted.map((s, i) => ({ entityId: s.entityId, affinity: s.affinity!, rank: sorted.findIndex((x) => x.affinity === s.affinity) + 1 }));
}

export function pressureResult(show: Opportunity, views: PressureTest['views'], now = Date.now(), policyName: PressureTest['policyName'] = 'balanced'): PressureTest {
  const rows = show.roster.map((c): PressureRow => {
    const q = qualify(c, show, now);
    const rank = (v: RankingView) => !v.error ? v.scores.find((s) => s.entityId === c.mapping.entityId)?.rank ?? null : null;
    const actRank = q.status === 'eligible' ? rank(views.act) : null;
    const sceneRank = q.status === 'eligible' ? rank(views.scene) : null;
    return { ...q, name: c.name, actRank, sceneRank, jointRank: q.status === 'eligible' ? rank(views.joint) : null, worstRank: actRank !== null && sceneRank !== null ? Math.max(actRank, sceneRank) : null };
  });
  const eligible = rows.filter((r) => r.status === 'eligible');
  const gate = Math.max(1, policyName === 'strict' ? Math.ceil(eligible.length / 2) : eligible.length - 1);
  const cleared = eligible.filter((r) => r.worstRank !== null && r.worstRank <= gate).sort((a, b) => a.worstRank! - b.worstRank! || (a.actRank! + a.sceneRank!) - (b.actRank! + b.sceneRank!));
  // A genuine policy tie is a human question, not hidden ID-order preference.
  const tie = cleared.length > 1 && cleared[0].worstRank === cleared[1].worstRank && cleared[0].actRank! + cleared[0].sceneRank! === cleared[1].actRank! + cleared[1].sceneRank!;
  const selected = !views.act.error && !views.scene.error && !tie ? cleared[0] ?? null : null;
  // A deterministic factual baseline with the SAME inventory, budget and qualification.
  // Genre overlap is deliberately simple and labeled, not an uninformed LLM strawman.
  const baseline = show.roster.filter((c) => eligible.some((r) => r.id === c.id)).sort((a, b) => a.fee!.value - b.fee!.value || a.name.localeCompare(b.name))[0] ?? null;
  return {
    opportunityId: show.id, version: show.version, rows, views, selectedId: selected?.id ?? null, baselineId: baseline?.id ?? null,
    policyName,
    policy: `Wanted's ${policyName} rule: clear the top ${gate} of ${eligible.length} in both contexts; minimize the worse rank, then total rank. Ties need an operator. Joint affinity is shown separately, never treated as audience union.`,
    explanation: selected ? `${selected.name} clears both contexts. Prepare a request, not a prediction of ticket sales.` : tie ? 'Two candidates tie under this policy. Ask the operator rather than invent a winner.' : 'No defensible bridge yet. Check the missing evidence, refine the scene, or try another date or bill.',
    observedAt: now,
  };
}
